//! C ABI for the firmware (node and loader): one global network stack,
//! driven from the radio task only (no locking here). The header is
//! generated by cbindgen (swarm_net.h). No panic handler: the staticlib's
//! root crate provides it (swarm_node for the node, swarm/loader_rs for the
//! loader).

use core::ffi::c_void;

use crate::crypto::{HMAC_KEY_LEN, P256_PUBLIC_KEY_LEN};
use crate::manifest::{self, Manifest};
use crate::net::{FrameKind, Net, SUMMARY_LEN_MAX};
use crate::update::{Flash, Status};

/// Longest encoded Summary (swarm.v1 `Summary`, variable length): what a POLL carries.
/// `swarm_net_summary` never writes more.
pub const SWARM_NET_SUMMARY_MAX: usize = 35;
const _: () = assert!(SWARM_NET_SUMMARY_MAX == SUMMARY_LEN_MAX);
/// Largest link payload swarm_net_next_tx writes: the manifest frame, 114 bytes (a mesh
/// packet is at most 112, a firmware data chunk 110, a request 19).
pub const SWARM_NET_MAX_FRAME: usize = 114;
// Literal for cbindgen (it parses this file alone); pinned to the source.
const _: () = assert!(SWARM_NET_MAX_FRAME == crate::net::MAX_FRAME_PAYLOAD);
/// Longest serialized Manifest (swarm.v1 `Manifest` envelope): 114 bytes.
pub const SWARM_NET_MANIFEST_MAX: usize = 114;
const _: () = assert!(SWARM_NET_MANIFEST_MAX == manifest::MAX_ENCODED);
/// Mesh payload limit for swarm_net_send / swarm_net_next_app.
pub const SWARM_NET_MAX_PAYLOAD: usize = 88;
const _: () = assert!(SWARM_NET_MAX_PAYLOAD == crate::mesh::MAX_PAYLOAD);
pub const SWARM_NET_KIND_MESH: i32 = 1;
pub const SWARM_NET_KIND_FW_REQUEST: i32 = 2;
pub const SWARM_NET_KIND_FW_DATA: i32 = 3;
/// A signed manifest, link broadcast (FRAME_TYPE_FW_MANIFEST), never relayed.
pub const SWARM_NET_KIND_FW_MANIFEST: i32 = 4;
pub const SWARM_NET_CHANGED_SWARM: u32 = 1;
pub const SWARM_NET_CHANGED_OVERRIDES: u32 = 2;
pub const SWARM_NET_CHANGED_FW_READY: u32 = 4;

/// The staging partition, provided by the firmware.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct SwarmFlashOps {
    pub ctx: *mut c_void,
    pub capacity: u32,
    pub erase: extern "C" fn(ctx: *mut c_void, offset: u32, len: u32) -> bool,
    pub write: extern "C" fn(ctx: *mut c_void, offset: u32, data: *const u8, len: usize) -> bool,
    pub read: extern "C" fn(ctx: *mut c_void, offset: u32, out: *mut u8, len: usize) -> bool,
}

struct CFlash(SwarmFlashOps);

impl Flash for CFlash {
    fn capacity(&self) -> u32 {
        self.0.capacity
    }
    fn erase(&mut self, offset: u32, len: u32) -> bool {
        (self.0.erase)(self.0.ctx, offset, len)
    }
    fn write(&mut self, offset: u32, data: &[u8]) -> bool {
        (self.0.write)(self.0.ctx, offset, data.as_ptr(), data.len())
    }
    fn read(&mut self, offset: u32, buf: &mut [u8]) -> bool {
        (self.0.read)(self.0.ctx, offset, buf.as_mut_ptr(), buf.len())
    }
}

static mut NET: Option<Net> = None;
static mut FLASH: Option<CFlash> = None;

/// The global stack and its flash, if initialized. For other Rust crates
/// in the same staticlib (swarm_node applies mesh settings through it).
#[allow(static_mut_refs)]
pub fn with_net<R>(f: impl FnOnce(&mut Net, &mut dyn Flash) -> R) -> Option<R> {
    unsafe {
        match (NET.as_mut(), FLASH.as_mut()) {
            (Some(n), Some(fl)) => Some(f(n, fl)),
            _ => None,
        }
    }
}

unsafe fn slice<'a>(p: *const u8, len: usize) -> &'a [u8] {
    if p.is_null() || len == 0 {
        &[]
    } else {
        core::slice::from_raw_parts(p, len)
    }
}

unsafe fn key32(p: *const u8) -> Option<[u8; HMAC_KEY_LEN]> {
    if p.is_null() {
        return None;
    }
    let mut k = [0u8; HMAC_KEY_LEN];
    k.copy_from_slice(core::slice::from_raw_parts(p, HMAC_KEY_LEN));
    Some(k)
}

/// `hmac_key`: 32 bytes or null (not provisioned). `fw_key`: 65-byte
/// uncompressed P-256 public key. `running`: installed firmware version.
#[no_mangle]
pub unsafe extern "C" fn swarm_net_init(me: u16, hmac_key: *const u8, fw_key: *const u8, running: u32, seed: u32,
                                        flash: *const SwarmFlashOps) {
    let mut pk = [0u8; P256_PUBLIC_KEY_LEN];
    pk.copy_from_slice(core::slice::from_raw_parts(fw_key, P256_PUBLIC_KEY_LEN));
    NET = Some(Net::new(me, key32(hmac_key), pk, running, seed));
    FLASH = Some(CFlash(*flash));
    with_net(|n, f| n.updater.boot(f));
}

#[no_mangle]
pub unsafe extern "C" fn swarm_net_set_hmac_key(key: *const u8) {
    let k = key32(key);
    with_net(|n, _| n.settings.set_key(k));
}

/// This node's encoded swarm.v1 Summary (for the POLL's `summary` field) into `out`
/// (`cap` >= SWARM_NET_SUMMARY_MAX): its length (variable, 0..=SWARM_NET_SUMMARY_MAX), or 0
/// if the stack is not initialized or `cap` is too small.
#[no_mangle]
pub unsafe extern "C" fn swarm_net_summary(out: *mut u8, cap: usize) -> usize {
    match with_net(|n, _| n.summary()) {
        Some((b, len)) if len <= cap => {
            core::ptr::copy_nonoverlapping(b.as_ptr(), out, len);
            len
        }
        _ => 0,
    }
}

/// This node's own summary, decoded (what UpdateServers needs: no byte parsing).
#[repr(C)]
#[derive(Clone, Copy, Default)]
pub struct SwarmNetSummary {
    pub running: u32,
    pub staged: u32,
    pub pages: u16,
    pub total: u16,
    pub generation: u32,
}

/// Fill `out` with this node's own summary (zeros if the stack is not initialized).
#[no_mangle]
pub unsafe extern "C" fn swarm_net_own_summary(out: *mut SwarmNetSummary) {
    let s = with_net(|n, _| n.own_summary()).unwrap_or_default();
    *out = SwarmNetSummary { running: s.running, staged: s.staged, pages: s.pages, total: s.total, generation: s.generation };
}

/// A neighbour's POLL `summary` bytes (a swarm.v1 Summary, any length up to
/// SWARM_NET_SUMMARY_MAX; malformed ones are ignored). `from`: the POLL's `src`.
#[no_mangle]
pub unsafe extern "C" fn swarm_net_on_summary(t_us: i64, from: u16, data: *const u8, len: usize) {
    let b = slice(data, len);
    with_net(|n, _| n.on_summary(t_us, from, b));
}

#[no_mangle]
pub unsafe extern "C" fn swarm_net_on_mesh(t_us: i64, data: *const u8, len: usize, rssi: f32) {
    let b = slice(data, len);
    with_net(|n, f| n.on_mesh(t_us, b, rssi, f));
}

#[no_mangle]
pub unsafe extern "C" fn swarm_net_on_fw_request(t_us: i64, data: *const u8, len: usize) {
    let b = slice(data, len);
    with_net(|n, _| n.on_fw_request(t_us, b));
}

/// A FRAME_TYPE_FW_MANIFEST link frame's payload (a swarm.v1 Manifest, <=
/// SWARM_NET_MANIFEST_MAX bytes): adopted if its signature checks, it is newer than what runs
/// and is staged, and it fits. Never relay it.
#[no_mangle]
pub unsafe extern "C" fn swarm_net_on_fw_manifest(t_us: i64, data: *const u8, len: usize) {
    let _ = t_us; // accepted for symmetry with the other rx entry points
    let b = slice(data, len);
    with_net(|n, f| n.on_fw_manifest(b, f));
}

#[no_mangle]
pub unsafe extern "C" fn swarm_net_on_fw_data(t_us: i64, data: *const u8, len: usize) {
    let b = slice(data, len);
    with_net(|n, f| n.on_fw_data(t_us, b, f));
}

#[no_mangle]
pub extern "C" fn swarm_net_on_my_slot() {
    with_net(|n, _| n.on_my_slot());
}

#[no_mangle]
pub extern "C" fn swarm_net_poll(t_us: i64) {
    with_net(|n, f| n.poll(t_us, f));
}

/// Next frame for this slot into `out` (`cap` >= SWARM_NET_MAX_FRAME): its
/// length, or 0. `kind`: SWARM_NET_KIND_*; `dest`: link destination (0xFFFF for
/// broadcast, i.e. leave LinkFrame.dst absent). The bytes are the LinkFrame `payload` of
/// type MESH / FW_REQUEST / FW_DATA / FW_MANIFEST respectively.
#[no_mangle]
pub unsafe extern "C" fn swarm_net_next_tx(t_us: i64, out: *mut u8, cap: usize, kind: *mut i32, dest: *mut u16) -> usize {
    let buf = core::slice::from_raw_parts_mut(out, cap);
    match with_net(|n, f| n.next_tx(t_us, buf, f)).flatten() {
        Some((k, len)) => {
            let (kc, d) = match k {
                FrameKind::Mesh => (SWARM_NET_KIND_MESH, 0xFFFF),
                FrameKind::FwRequest { dest } => (SWARM_NET_KIND_FW_REQUEST, dest),
                FrameKind::FwData => (SWARM_NET_KIND_FW_DATA, 0xFFFF),
                FrameKind::FwManifest => (SWARM_NET_KIND_FW_MANIFEST, 0xFFFF),
            };
            *kind = kc;
            *dest = d;
            len
        }
        None => 0,
    }
}

/// SWARM_NET_CHANGED_* bits since the last call.
#[no_mangle]
pub extern "C" fn swarm_net_take_changes() -> u32 {
    with_net(|n, _| {
        let c = n.take_changes();
        (c.settings.swarm as u32) * SWARM_NET_CHANGED_SWARM
            | (c.settings.overrides as u32) * SWARM_NET_CHANGED_OVERRIDES
            | (c.fw_ready as u32) * SWARM_NET_CHANGED_FW_READY
    })
    .unwrap_or(0)
}

/// A packet for the firmware/host (app ports, settings reports): payload
/// (at most SWARM_NET_MAX_PAYLOAD bytes) into `out`, its length; -1 if none. A settings
/// report's payload is a swarm.v1 SettingsReport.
#[no_mangle]
pub unsafe extern "C" fn swarm_net_next_app(origin: *mut u16, dest: *mut u16, port: *mut u8, hops: *mut u8,
                                            rssi: *mut f32, out: *mut u8, cap: usize) -> i32 {
    let Some(Some(a)) = with_net(|n, _| n.next_app()) else { return -1 };
    let len = a.len.min(cap);
    core::ptr::copy_nonoverlapping(a.payload.as_ptr(), out, len);
    *origin = a.origin;
    *dest = a.dest;
    *port = a.port;
    *hops = a.hops;
    *rssi = a.rssi;
    len as i32
}

#[no_mangle]
pub unsafe extern "C" fn swarm_net_host_bundle(data: *const u8, len: usize) -> bool {
    let b = slice(data, len);
    with_net(|n, _| n.host_bundle(b)).unwrap_or(false)
}

/// Set (`set`) or clear one override on this node (USB: trusted).
#[no_mangle]
pub extern "C" fn swarm_net_local_override(key: u16, value: u32, set: bool) {
    with_net(|n, _| n.local_override(key, if set { Some(value) } else { None }));
}

/// A signed manifest from the host (USB): the serialized swarm.v1 Manifest, up to
/// SWARM_NET_MANIFEST_MAX bytes. True if adopted (or already staged).
#[no_mangle]
pub unsafe extern "C" fn swarm_net_host_manifest(data: *const u8, len: usize) -> bool {
    let b = slice(data, len);
    with_net(|n, f| n.host_manifest(b, f)).unwrap_or(false)
}

#[no_mangle]
pub unsafe extern "C" fn swarm_net_host_chunk(t_us: i64, page: u16, chunk: u8, data: *const u8, len: usize) {
    let b = slice(data, len);
    with_net(|n, f| n.host_chunk(t_us, page, chunk, b, f));
}

/// Queue a mesh packet (`len` <= SWARM_NET_MAX_PAYLOAD, `port` <= 127); its id, or -1 if the
/// outbox is full or an argument is out of range.
#[no_mangle]
pub unsafe extern "C" fn swarm_net_send(dest: u16, port: u8, data: *const u8, len: usize, want_ack: bool) -> i32 {
    let b = slice(data, len);
    match with_net(|n, _| n.send(dest, port, b, want_ack)).flatten() {
        Some(id) => id as i32,
        None => -1,
    }
}

// ---- persistence

/// The tagged swarm bundle (to store), its length; 0 if none.
#[no_mangle]
pub unsafe extern "C" fn swarm_net_bundle(out: *mut u8, cap: usize) -> usize {
    with_net(|n, _| {
        let b = n.settings.bundle();
        if b.len() > cap {
            return 0;
        }
        core::ptr::copy_nonoverlapping(b.as_ptr(), out, b.len());
        b.len()
    })
    .unwrap_or(0)
}

#[no_mangle]
pub unsafe extern "C" fn swarm_net_load_bundle(data: *const u8, len: usize) -> bool {
    let b = slice(data, len);
    with_net(|n, _| n.settings.load_bundle(b)).unwrap_or(false)
}

#[no_mangle]
pub unsafe extern "C" fn swarm_net_overrides(out: *mut u8, cap: usize) -> usize {
    let buf = core::slice::from_raw_parts_mut(out, cap);
    with_net(|n, _| n.settings.save_overrides(buf)).flatten().unwrap_or(0)
}

#[no_mangle]
pub unsafe extern "C" fn swarm_net_load_overrides(data: *const u8, len: usize) -> bool {
    let b = slice(data, len);
    with_net(|n, _| n.settings.load_overrides(b)).unwrap_or(false)
}

/// Raw stored value for `key`: 2 override, 1 swarm, 0 neither.
#[no_mangle]
pub unsafe extern "C" fn swarm_net_layer_get(key: u16, swarm: *mut u32, over: *mut u32) -> i32 {
    with_net(|n, _| {
        let s = n.settings.swarm.get(key);
        let o = n.settings.overrides.get(key);
        *swarm = s.unwrap_or(0);
        *over = o.unwrap_or(0);
        (s.is_some() as i32) | (o.is_some() as i32) << 1
    })
    .unwrap_or(0)
}

// ---- firmware image

/// The staged image's version, size and SHA-256 (from its signed manifest), replacing the
/// fixed-offset reads of the old packed manifest. False (outputs untouched) if nothing is
/// staged. This says what is staged, not that the image is complete: see
/// swarm_net_verify_staged.
#[no_mangle]
pub unsafe extern "C" fn swarm_net_staged_manifest_info(version: *mut u32, size: *mut u32, sha256_out: *mut u8) -> bool {
    match with_net(|n, _| n.updater.manifest()).flatten() {
        Some(m) => {
            *version = m.version;
            *size = m.size;
            core::ptr::copy_nonoverlapping(m.sha256.as_ptr(), sha256_out, 32);
            true
        }
        None => false,
    }
}

/// The running firmware passed its health checks: from now on this node
/// may offer and serve its image (canary rule).
#[no_mangle]
pub extern "C" fn swarm_net_set_validated(validated: bool) {
    with_net(|n, _| n.updater.set_validated(validated));
}

/// Re-hash the staged image against its signed manifest (the loader runs
/// this right before installing).
#[no_mangle]
pub extern "C" fn swarm_net_verify_staged() -> bool {
    with_net(|n, f| n.updater.manifest().is_some() && n.updater.verify_image(f)).unwrap_or(false)
}

/// Check a serialized Manifest's signature (e.g. one received over USB): `data`/`len` the
/// envelope (<= SWARM_NET_MANIFEST_MAX), `fw_key` the 65-byte public key.
#[no_mangle]
pub unsafe extern "C" fn swarm_net_manifest_ok(data: *const u8, len: usize, fw_key: *const u8) -> bool {
    let Some(m) = Manifest::decode(slice(data, len)) else { return false };
    let mut pk = [0u8; P256_PUBLIC_KEY_LEN];
    pk.copy_from_slice(core::slice::from_raw_parts(fw_key, P256_PUBLIC_KEY_LEN));
    m.verify(&pk)
}

// ---- status

/// A neighbour's last POLL summary.
#[repr(C)]
#[derive(Clone, Copy, Default)]
pub struct SwarmNetNeighbour {
    pub id: u16,
    pub fw_pages: u16,
    pub fw_total: u16,
    pub fw_running: u32,
    pub fw_staged: u32,
    pub last_us: i64,
}

/// Neighbours heard within `max_age_us` of `t_us` into `out`; the count.
#[no_mangle]
pub unsafe extern "C" fn swarm_net_neighbours(t_us: i64, max_age_us: i64, out: *mut SwarmNetNeighbour, cap: usize) -> usize {
    let out = core::slice::from_raw_parts_mut(out, cap);
    with_net(|n, _| {
        let mut k = 0;
        for (id, s, last) in n.updater.neighbours() {
            if k == cap || t_us - last > max_age_us {
                continue;
            }
            out[k] = SwarmNetNeighbour {
                id,
                fw_pages: s.pages,
                fw_total: s.total,
                fw_running: s.running,
                fw_staged: s.staged,
                last_us: last,
            };
            k += 1;
        }
        k
    })
    .unwrap_or(0)
}

#[repr(C)]
#[derive(Clone, Copy, Default)]
pub struct SwarmNetStatus {
    pub fw_running: u32,
    pub fw_staged: u32,
    pub fw_pages: u16,
    pub fw_total: u16,
    /// 0 idle, 1 receiving, 2 ready to install, 3 serving.
    pub fw_status: u8,
    pub has_key: bool,
    pub settings_generation: u32,
    pub override_seq: u32,
    pub mesh_originated: u32,
    pub mesh_delivered: u32,
    pub mesh_relayed: u32,
    pub mesh_relays_cancelled: u32,
    pub mesh_duplicates: u32,
    pub mesh_retries: u32,
    pub mesh_failed: u32,
    pub fw_chunks_written: u32,
    pub fw_chunks_served: u32,
    pub fw_requests_sent: u32,
    pub fw_rejected: u32,
    pub settings_applied: u32,
    pub settings_rejected_tag: u32,
    pub settings_rejected_replay: u32,
    pub fw_data_rx: u32,
    pub fw_chunks_duplicate: u32,
    pub fw_chunks_ignored: u32,
    pub fw_req_quiet: u32,
    pub fw_req_no_server: u32,
}

#[no_mangle]
pub unsafe extern "C" fn swarm_net_status(out: *mut SwarmNetStatus) {
    let s = with_net(|n, _| {
        let f = n.updater.summary();
        let m = n.mesh.stats;
        let u = n.updater.stats;
        let st = n.settings.stats;
        SwarmNetStatus {
            fw_running: f.running,
            fw_staged: f.staged,
            fw_pages: f.pages,
            fw_total: f.total,
            fw_status: match n.updater.status() {
                Status::Idle => 0,
                Status::Receiving => 1,
                Status::Ready => 2,
                Status::Serving => 3,
            },
            has_key: n.settings.has_key(),
            settings_generation: n.settings.generation(),
            override_seq: n.settings.override_seq,
            mesh_originated: m.originated,
            mesh_delivered: m.delivered,
            mesh_relayed: m.relayed,
            mesh_relays_cancelled: m.relays_cancelled,
            mesh_duplicates: m.duplicates,
            mesh_retries: m.retries,
            mesh_failed: m.failed,
            fw_chunks_written: u.chunks_written,
            fw_chunks_served: u.chunks_served,
            fw_requests_sent: u.requests_sent,
            fw_rejected: u.rejected_signature + u.verify_failed,
            settings_applied: st.bundles_applied + st.overrides_applied,
            settings_rejected_tag: st.rejected_tag,
            settings_rejected_replay: st.rejected_replay,
            fw_data_rx: u.data_rx,
            fw_chunks_duplicate: u.chunks_duplicate,
            fw_chunks_ignored: u.chunks_ignored,
            fw_req_quiet: u.req_quiet,
            fw_req_no_server: u.req_no_server,
        }
    })
    .unwrap_or_default();
    *out = s;
}
